#!/usr/bin/env python3
"""Scoped repair of the secondary launcher FPS budget; independent adapter only."""
import argparse,ast,base64,hashlib,os,shutil,socket,stat,tempfile,zlib
from pathlib import Path
OLD='75c4b815ca592c400b29a95f2438dccf8328d20710a21c662de95ec7ab736a0d'
NEW='70ca5c9c9eacecddc57581e204b715da1f8711bcb579a089b1ac3d9f5ed6d57f'
PAYLOAD=''
def main():
 p=argparse.ArgumentParser();p.add_argument('--pasta',type=Path,default=Path.home()/'SNAKE_REYERS_TERMUX_0_2');a=p.parse_args();root=a.pasta.expanduser().resolve();target=root/'snake_termux/native.py'
 if target.is_symlink() or not target.is_file() or not (root/'snake_termux/presentation.py').is_file():p.error('Pasta da adaptação 0.3.4 não reconhecida.')
 current=target.read_bytes();digest=hashlib.sha256(current).hexdigest()
 if digest==NEW:print('A correção do limite já está aplicada.');return
 if digest!=OLD:p.error('Seu native.py difere da base 0.3.4 esperada. Nada foi substituído; preserve suas alterações.')
 try:connection=socket.create_connection(('127.0.0.1',9393),timeout=.5)
 except OSError:pass
 else:connection.close();p.error('Pare o iniciador do jogo com Ctrl+C antes de aplicar esta correção. Nenhum processo foi encerrado.')
 raw=zlib.decompress(base64.b64decode(PAYLOAD))
 if hashlib.sha256(raw).hexdigest()!=NEW:raise ValueError('Integridade da correção inválida.')
 ast.parse(raw.decode('utf-8'));directory=root/'state/launcher-backups';directory.mkdir(parents=True,exist_ok=True);backup=Path(tempfile.mkdtemp(prefix='wrapper-fps-',dir=directory));shutil.copy2(target,backup/'native-before.py')
 temporary=None
 try:
  fd,name=tempfile.mkstemp(prefix='.native-wrapper-',dir=target.parent);temporary=Path(name)
  with os.fdopen(fd,'wb') as stream:stream.write(raw)
  temporary.chmod(stat.S_IMODE(target.stat().st_mode));os.replace(temporary,target)
 finally:
  if temporary:temporary.unlink(missing_ok=True)
 print('Limite do perfil respeitado também pelo iniciador secundário. Perfil e modelos não foram trocados.')
 print('Backup: '+str(backup/'native-before.py'))
 print('Para reverter, com o jogo parado: copie esse backup para snake_termux/native.py.')
 print('Para iniciar: cd '+str(root)+' && bash start.sh')
if __name__=='__main__':main()
